270	function splitIntoChunks(text: string, size: number, overlap: number): string[] {
271	  const sentences = text.match(/[^。！？.!?\n]+[。！？.!?\n]?/g) || [text];
272	  const chunks: string[] = [];
273	  let current = '';
274	  for (const sentence of sentences) {
275	    if (current.length + sentence.length > size && current.length > 0) {
276	      chunks.push(current.trim());
277	      const words = current.split(/\s+/);
278	      let keep = '';
279	      let keepLen = 0;
280	      for (let i = words.length - 1; i >= 0; i--) {
281	        if (keepLen + words[i].length > overlap) break;
282	        keep = words[i] + ' ' + keep;
283	        keepLen += words[i].length + 1;
284	      }
285	      current = keep.trim() + sentence;
286	    } else {
287	      current += sentence;
288	    }
289	  }
290	  if (current.trim()) chunks.push(current.trim());
291	  return chunks;
292	}
