294	interface ParsedFile {
295	  fileName: string;
296	  chunks: Array<{ id: string; text: string; fileName: string; chunkIndex: number }>;
297	}
298	
299	function parseFile(fileName: string, content: string, chunkSize: number, chunkOverlap: number): ParsedFile {
300	  const chunks: ParsedFile['chunks'] = [];
301	  if (fileName.endsWith('.json')) {
302	    try {
303	      const arr = JSON.parse(content);
304	      if (Array.isArray(arr)) {
305	        arr.forEach((item: { id?: string; title?: string; text?: string }, idx: number) => {
306	          const text = item.text || item.title || '';
307	          if (!text) return;
308	          const subChunks = splitIntoChunks(text, chunkSize, chunkOverlap);
309	          subChunks.forEach((c, ci) => {
310	            chunks.push({
311	              id: `${item.id || idx}_${ci}`,
312	              text: c,
313	              fileName: item.title || fileName,
314	              chunkIndex: ci,
315	            });
316	          });
317	        });
318	      }
319	    } catch {
320	      const textChunks = splitIntoChunks(content, chunkSize, chunkOverlap);
321	      textChunks.forEach((c, i) => {
322	        chunks.push({ id: `${fileName}_${i}`, text: c, fileName, chunkIndex: i });
323	      });
324	    }
325	  } else {
326	    const textChunks = splitIntoChunks(content, chunkSize, chunkOverlap);
327	    textChunks.forEach((c, i) => {
328	      chunks.push({ id: `${fileName}_${i}`, text: c, fileName, chunkIndex: i });
329	    });
330	  }
331	  return { fileName, chunks };
332	}
