334	async function handleImport() {
335	  if (!state.currentCourse) { showToast('请先选择课程', 'error'); return; }
336	  if (!state.modelReady) { showToast('模型尚未加载完成', 'error'); return; }
337	
338	  const fileInput = document.getElementById('file-input') as HTMLInputElement;
339	  const files = fileInput?.files;
340	  if (!files || files.length === 0) { showToast('请选择文件', 'error'); return; }
341	
342	  const chunkSize = parseInt((document.getElementById('chunk-size') as HTMLInputElement)?.value || '300');
343	  const chunkOverlap = parseInt((document.getElementById('chunk-overlap') as HTMLInputElement)?.value || '50');
344	
345	  const progressArea = document.getElementById('import-progress-area');
346	  const statusText = document.getElementById('import-status-text');
347	  const progressFill = document.getElementById('import-progress-fill');
348	  const fileListEl = document.getElementById('import-file-list');
349	  if (progressArea) progressArea.style.display = 'block';
350	  if (fileListEl) clearChildren(fileListEl);
351	
352	  try {
353	    const allParsed: ParsedFile[] = [];
354	    for (const file of Array.from(files)) {
355	      const content = await file.text();
356	      const parsed = parseFile(file.name, content, chunkSize, chunkOverlap);
357	      allParsed.push(parsed);
358	      if (fileListEl) {
359	        const item = el('div', { className: 'file-item' }, `${file.name} — ${parsed.chunks.length} 个分块`);
360	        fileListEl.appendChild(item);
361	      }
362	    }
363	
364	    const totalChunks = allParsed.reduce((sum, p) => sum + p.chunks.length, 0);
365	    if (totalChunks === 0) { showToast('未解析到任何内容', 'error'); return; }
366	
367	    if (statusText) statusText.textContent = `正在向量化 0/${totalChunks}...`;
368	    if (progressFill) progressFill.style.width = '0%';
369	
370	    const allChunks = allParsed.flatMap((p) => p.chunks);
371	    const batchSize = 16;
372	    const embedded: Array<typeof allChunks[0] & { embedding: number[] }> = [];
373	
374	    for (let i = 0; i < allChunks.length; i += batchSize) {
375	      const batch = allChunks.slice(i, i + batchSize);
376	      const texts = batch.map((c) => c.text);
377	      const vectors = await embedTexts(texts);
378	      batch.forEach((c, j) => {
379	        embedded.push({ ...c, embedding: vectors[j] });
380	      });
381	      const done = Math.min(i + batchSize, totalChunks);
382	      if (statusText) statusText.textContent = `正在向量化 ${done}/${totalChunks}...`;
383	      if (progressFill) progressFill.style.width = `${(done / totalChunks) * 80}%`;
384	    }
385	
386	    if (statusText) statusText.textContent = '正在写入 seekdb...';
387	    if (progressFill) progressFill.style.width = '85%';
388	
389	    const importBatchSize = 50;
390	    for (let i = 0; i < embedded.length; i += importBatchSize) {
391	      const batch = embedded.slice(i, i + importBatchSize);
392	      await api.importChunks(
393	        state.currentCourse,
394	        batch.map((c) => ({
395	          id: c.id,
396	          text: c.text,
397	          embedding: c.embedding,
398	          fileName: c.fileName,
399	          chunkIndex: c.chunkIndex,
400	        }))
401	      );
402	      const done = Math.min(i + importBatchSize, embedded.length);
403	      if (progressFill) progressFill.style.width = `${85 + (done / embedded.length) * 15}%`;
404	    }
405	
406	    if (statusText) statusText.textContent = `导入完成: ${embedded.length} 个分块`;
407	    if (progressFill) progressFill.style.width = '100%';
408	    showToast(`成功导入 ${embedded.length} 个分块`, 'success');
409	    refreshCollections();
410	  } catch (e) {
411	    const msg = e instanceof Error ? e.message : String(e);
412	    showToast(`导入失败: ${msg}`, 'error');
413	    if (statusText) statusText.textContent = `导入失败: ${msg}`;
414	  }
415	}
