447	  const query = input?.value.trim();
448	  if (!query) { showToast('请输入查询内容', 'error'); return; }
449	
450	  const resultsEl = document.getElementById('search-results');
451	  const timingEl = document.getElementById('search-timing');
452	  if (resultsEl) {
453	    clearChildren(resultsEl);
454	    resultsEl.appendChild(el('div', { className: 'empty-hint' }, '检索中...'));
455	  }
456	
457	  try {
458	    const t0 = performance.now();
459	    const vector = await embedSingle(query);
460	    const t1 = performance.now();
461	
462	    const { results } = await api.search(state.currentCourse, query, vector, 10);
463	    const t2 = performance.now();
464	
465	    state.lastSearchTime = {
466	      embed: Math.round(t1 - t0),
467	      search: Math.round(t2 - t1),
468	      total: Math.round(t2 - t0),
469	    };
470	    if (timingEl) {
471	      timingEl.textContent = `向量化: ${state.lastSearchTime.embed}ms | seekdb 检索: ${state.lastSearchTime.search}ms | 总计: ${state.lastSearchTime.total}ms`;
472	    }
473	
474	    if (!resultsEl) return;
475	    clearChildren(resultsEl);
476	    if (results.length === 0) {
477	      resultsEl.appendChild(el('div', { className: 'empty-hint' }, '未找到相关结果'));
478	      return;
479	    }
480	
481	    for (const r of results) {
482	      resultsEl.appendChild(buildSearchResultCard(r, query));
483	    }
484	  } catch (e) {
485	    const msg = e instanceof Error ? e.message : String(e);
486	    showToast(`检索失败: ${msg}`, 'error');
487	    if (resultsEl) {
488	      clearChildren(resultsEl);
489	      resultsEl.appendChild(el('div', { className: 'empty-hint' }, `检索失败: ${msg}`));
490	    }
491	  }
