516	function highlightInto(parent: HTMLElement, text: string, query: string) {
517	  if (!query.trim()) {
518	    parent.appendChild(document.createTextNode(text));
519	    return;
520	  }
521	  const words = query.split(/\s+/).filter(Boolean);
522	  if (words.length === 0) {
523	    parent.appendChild(document.createTextNode(text));
524	    return;
525	  }
526	  const escaped = words.map((w) => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
527	  const regex = new RegExp(`(${escaped.join('|')})`, 'gi');
528	  const parts = text.split(regex);
529	  for (const part of parts) {
530	    if (regex.test(part)) {
531	      const mark = el('mark');
532	      mark.textContent = part;
533	      parent.appendChild(mark);
534	    } else {
535	      parent.appendChild(document.createTextNode(part));
536	    }
537	    regex.lastIndex = 0;
538	  }
539	}
